import{printedArtwork}from'../../modeling/artwork.js';import{spec}from'./dimensions.js';const front=new URL('./artwork/front.png',import.meta.url).href,axis=new URL('./artwork/axis.png',import.meta.url).href,back=new URL('./artwork/back.png',import.meta.url).href;
export function addStickers(host){const out=[];for(const[face,url]of[['front',front],['axis',axis],['back',back]]){const target=host.bmm350Assembly.labels[face];if(target)out.push(...(printedArtwork(host,{target,url,size:spec.labels[face].size,position:spec.labels[face].position,face:face==='back'?'back':'front',depth:.12,artworkKind:'source-vector-raster',name:'BMM350 exactown U231 '+face+' originalbodylabel'})??[]));}return out;}
